page.css:
*{box-sizing:border-box}
:root{
  /* static accents — same in both themes. Main = yellow; blue = the one 'touch' accent */
  --amber:#f7a80a;--amber-l:#ffc247;--gold:#ffd874;--amber-d:#c47a08;
  --cyan:#f7a80a;--cyan-d:#c47a08;--violet:#f7a80a;--violet-d:#c47a08;
  --blue:#3b82f6;--blue-l:#7ab0ff;--pink:#f7a80a;--green:#34e0a1;
  --grad:linear-gradient(120deg,#ffd874,#f7a80a);
  --grad-b:linear-gradient(120deg,#7ab0ff,#3b82f6);
  --gcyan:rgba(247,168,10,.55);--gviolet:rgba(247,168,10,.42);
  --gut:clamp(18px,5vw,44px);
  --fdisp:'Sora',system-ui,sans-serif;--fbody:'Inter',system-ui,sans-serif;
  --r:18px;
}
/* ---- dark theme (default) — swappable tokens live on .site ---- */
:root{
  --bg:#07080f;--bg2:#0b0d16;--bg3:#0e1018;
  --ink:#f4f6fb;--ink2:#c9cfdd;--mut:#8b93a8;
  --line:rgba(255,255,255,.10);--line2:rgba(255,255,255,.18);
  --glass:rgba(255,255,255,.045);--glass2:rgba(255,255,255,.08);
  --base:#0a0c15;--cream:#0c0e18;
  --hdrbg:#0a0d16;--hdrtext:#dbe2f5;--capbg:#0c0f1c;--menubg:#0d111d;
  --utilbg:#05060f;--utiltext:#9aa3c0;
  --shadow:0 24px 60px -28px rgba(0,0,0,.8);
  --glow:0 0 0 1px rgba(247,168,10,.3),0 18px 50px -18px rgba(247,168,10,.3),0 10px 40px -14px rgba(0,0,0,.5);
  --page-grad:radial-gradient(900px 600px at 12% -5%,rgba(247,168,10,.10),transparent 60%),radial-gradient(900px 620px at 92% 4%,rgba(59,130,246,.10),transparent 60%)}
/* ---- WHITE rows — light section to break up the dark ---- */
.rowlight{
  background:#f4f6fc;
  --ink:#0e1424;--ink2:#42506a;--mut:#697390;
  --line:rgba(14,20,36,.10);--line2:rgba(14,20,36,.16);
  --glass:#ffffff;--glass2:#eef2f9;
  --base:#f4f6fc;--cream:#f4f6fc;
  --glow:0 0 0 1px rgba(247,168,10,.35),0 18px 40px -20px rgba(247,168,10,.3),0 10px 30px -16px rgba(20,30,60,.15);
  color:var(--ink)}
.rowlight .vc,.rowlight .svc,.rowlight .rev,.rowlight .plan,.rowlight .ind,.rowlight .pstep{
  box-shadow:0 14px 36px -22px rgba(20,30,60,.3)}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);background-image:var(--page-grad);background-attachment:fixed;
  color:var(--ink);min-height:100vh;font-family:var(--fbody);
  font-size:16.5px;line-height:1.62;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;display:block}
svg{width:18px;height:18px;flex-shrink:0}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--fdisp);line-height:1.06;margin:0;letter-spacing:-.02em;font-weight:800}
p{margin:0 0 1em}
.wrap{max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{font-family:var(--fdisp);font-weight:700;font-size:.78rem;letter-spacing:.18em;
  text-transform:uppercase;color:var(--cyan)}
.k-amber{background:linear-gradient(100deg,#ffd874,#ffb23a 50%,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 16px rgba(247,168,10,.35))}
.k-green{background:var(--grad-b);-webkit-background-clip:text;background-clip:text;color:transparent}

.btn{display:inline-flex;align-items:center;gap:.5em;font-family:var(--fdisp);font-weight:700;
  font-size:.98rem;padding:.85em 1.5em;border-radius:999px;border:0;cursor:pointer;
  transition:transform .18s,box-shadow .18s,background .18s,border-color .18s;white-space:nowrap;position:relative}
.btn svg{width:18px;height:18px}
.btn-amber{background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;
  box-shadow:0 0 26px -4px rgba(247,168,10,.6),0 0 46px -12px rgba(247,168,10,.45)}
.btn-amber:hover{transform:translateY(-3px);box-shadow:0 0 36px -2px rgba(247,168,10,.8),0 0 60px -10px rgba(247,168,10,.5)}
.btn-ghost{background:var(--glass);color:#fff;border:1px solid var(--line2);backdrop-filter:blur(8px)}
.btn-ghost:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -6px var(--gcyan)}
.btn-dark{background:var(--glass2);color:#fff;border:1px solid var(--line)}
.btn-dark:hover{transform:translateY(-3px);border-color:var(--violet);box-shadow:0 0 24px -6px var(--gviolet)}
.btn-lg{padding:1.05em 1.9em;font-size:1.05rem}
.btn{max-width:100%}
@media(max-width:560px){.btn,.btn-lg{white-space:normal;text-align:center;line-height:1.25}.btn-lg{padding:.95em 1.35em;font-size:1rem}}

/* reveal is position-only so content is ALWAYS visible even if a CMS editor
   (e.g. the Nifty live editor) pauses or strips CSS animations */
.rv,.rv2,.rv3{opacity:1}
.rv{animation:rvIn .8s both}
.rv2{animation:rvIn .8s .12s both}
.rv3{animation:rvIn .8s .24s both}
@keyframes rvIn{from{transform:translateY(22px)}to{transform:none}}
@media (prefers-reduced-motion:reduce){
  .rv,.rv2,.rv3,.aurora,.marq-row,.spin,.pulse,.stage-char,.stage-ring,.fcard,.fc-ico,.orb{animation:none!important}
  html{scroll-behavior:auto}
}

/* ---------- utility bar ---------- */
.util{background:var(--utilbg);color:var(--utiltext);font-size:.82rem;border-bottom:1px solid var(--line)}
.util .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:8px;padding-bottom:8px}
.util a{color:var(--utiltext);transition:color .15s}
.util a:hover{color:var(--amber)}
.util-l,.util-r{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.util-l a{font-weight:500}
.util-ph{color:var(--ink)!important;font-family:var(--fdisp);font-weight:700;display:inline-flex;align-items:center;gap:6px}
.util-ph svg{width:15px;height:15px;color:var(--cyan)}
.util-login{display:inline-flex;align-items:center;gap:6px}
.util-login svg{width:14px;height:14px}
@media(max-width:820px){.util-l{display:none}}

/* ---------- header ---------- */
.hdr{position:sticky;top:0;z-index:1000}
.hdr .wrap{position:relative;max-width:1420px}
.navbar{position:relative;background:var(--hdrbg);border-bottom:1px solid var(--line);z-index:1000}
.navbar::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;
  background:linear-gradient(90deg,transparent,rgba(247,168,10,.6),rgba(59,130,246,.5),rgba(247,168,10,.6),transparent)}
.hdr-in{display:flex;align-items:center;gap:16px;padding-top:11px;padding-bottom:11px}
.brand{display:flex;align-items:center;flex-shrink:0;padding:10px 18px;border-radius:16px;
  background:linear-gradient(135deg,rgba(255,255,255,.1),rgba(255,255,255,.02));
  border:1px solid var(--line2);backdrop-filter:blur(10px);
  box-shadow:0 0 34px -12px rgba(247,168,10,.45),inset 0 1px 0 rgba(255,255,255,.14)}
.brand img{height:60px;width:auto}
.lg-d{filter:drop-shadow(0 0 16px rgba(247,168,10,.4))}
@media(max-width:1320px){.brand{padding:8px 12px}.brand img{height:46px}}
/* capsule nav — gradient glowing border */
.navcap{display:flex;align-items:center;margin:0 auto;border-radius:999px;padding:5px;position:relative;
  border:1.5px solid transparent;
  background:linear-gradient(var(--capbg),var(--capbg)) padding-box,linear-gradient(120deg,#f7a80a,#3b82f6 55%,#f7a80a) border-box;
  box-shadow:0 0 30px -10px rgba(247,168,10,.5),0 0 18px -12px rgba(59,130,246,.5)}
.nav{display:flex;align-items:center;gap:1px;margin:0}
.nav>li{position:static;list-style:none}
.nav ul{list-style:none;margin:0;padding:0}
.nav-lnk{display:inline-flex;align-items:center;gap:4px;color:var(--hdrtext);font-family:var(--fdisp);
  font-weight:600;font-size:.9rem;padding:9px 12px;border-radius:999px;white-space:nowrap;
  transition:background .15s,color .15s;cursor:pointer}
.nav-lnk:hover{background:var(--glass2);color:var(--ink)}
.nav-lnk svg{width:13px;height:13px;opacity:.7;transition:transform .2s}
.nav-mcta{display:none}
/* call-us block */
.callus{display:flex;align-items:center;gap:10px;flex-shrink:0;color:var(--ink)}
.callic{width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#ffc247,#f7a80a);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 0 18px -5px rgba(247,168,10,.6)}
.callic svg{width:18px;height:18px;color:#231704}
.callt small{display:block;font-size:.68rem;color:var(--mut);font-weight:600;line-height:1.35}
.callt b{font-family:var(--fdisp);font-size:.95rem;color:var(--ink);white-space:nowrap}
/* theme toggle */
.tglbl{width:42px;height:42px;border-radius:50%;border:1px solid var(--line2);background:var(--glass);
  display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;transition:.16s;color:var(--hdrtext)}
.tglbl:hover{border-color:var(--amber);color:var(--amber);box-shadow:0 0 18px -6px rgba(247,168,10,.6)}
.tglbl svg{width:19px;height:19px}
.tgmoon{display:none}
.themetog:checked ~ .site .tgsun{display:none}
.themetog:checked ~ .site .tgmoon{display:inline-flex}
.themetog:checked ~ .site .lg-d{display:none}
.themetog:checked ~ .site .lg-l{display:block}
/* arrow CTA */
.cta-arrow{display:inline-flex;align-items:center;gap:10px;background:linear-gradient(135deg,#ffc247,#f7a80a);
  color:#231704;font-family:var(--fdisp);font-weight:700;font-size:.9rem;padding:6px 7px 6px 18px;border-radius:999px;
  flex-shrink:0;box-shadow:0 0 24px -6px rgba(247,168,10,.55);transition:transform .18s,box-shadow .18s}
.cta-arrow:hover{transform:translateY(-2px);box-shadow:0 0 34px -4px rgba(247,168,10,.8)}
.cta-arrow .arrb{width:32px;height:32px;border-radius:50%;background:#231704;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.cta-arrow .arrb svg{width:16px;height:16px;color:#ffc247}

/* mega menu — right-anchored to .hdr .wrap */
.mega{position:absolute;top:100%;left:0;right:0;margin-top:13px;transform:translateY(8px);
  background:var(--menubg);color:var(--ink);border-radius:16px;
  box-shadow:0 40px 90px -30px rgba(0,0,0,.6),0 0 0 1px var(--line),0 0 60px -24px rgba(247,168,10,.4);
  padding:22px;width:auto;
  opacity:0;visibility:hidden;transition:opacity .22s,transform .22s,visibility .22s;z-index:1000;
  border:1px solid var(--line2)}
.mega::before{content:"";position:absolute;left:0;right:0;top:-15px;height:17px}
.mega.solo .mega-col{max-width:460px;margin:0 auto}
.nav>li:hover .mega,.nav>li:focus-within .mega{opacity:1;visibility:visible;transform:translateY(0)}
.nav>li:hover .nav-lnk svg{transform:rotate(180deg)}
.mega-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:20px 26px}
.mega-col h5{font-family:var(--fdisp);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;
  color:var(--amber);margin:0 0 10px;font-weight:800}
.mega-col a{display:block;padding:6px 0;font-size:.92rem;font-weight:500;color:var(--ink2);
  border-radius:6px;transition:color .14s,padding .14s}
.mega-col a:hover{color:var(--ink);padding-left:4px}
.mega-col a b{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.mega-foot{margin-top:16px;padding-top:14px;border-top:1px solid var(--line);
  display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:.88rem}
.mega-foot .btn{padding:.6em 1.1em;font-size:.86rem}
.mega-tag{color:var(--mut)}

.mtog,.mlbl,.acc{display:none}
.mlbl{width:44px;height:44px;border-radius:12px;background:var(--glass2);border:1px solid var(--line2);
  cursor:pointer;align-items:center;justify-content:center}
.mlbl svg{width:24px;height:24px;color:var(--ink)}

@media(max-width:1520px){.callus{display:none}}
@media(max-width:1320px){
  .navcap{margin:0;border:0;background:none;box-shadow:none;padding:0;position:static}
  .nav,.callus{display:none}
  .mlbl{display:inline-flex}
  .cta-arrow{margin-left:auto}
  .hdr-in{position:relative;gap:10px}
  .mtog:checked ~ .navcap .nav{display:flex}
  .nav{position:absolute;top:calc(100% + 14px);left:0;right:0;flex-direction:column;
    align-items:stretch;gap:2px;background:var(--menubg);color:var(--ink);border-radius:16px;
    padding:12px;box-shadow:var(--shadow),0 0 0 1px var(--line2);margin:0;max-height:74vh;overflow:auto;backdrop-filter:blur(20px)}
  .nav>li{width:100%}
  .nav-lnk{color:var(--ink);width:100%;justify-content:space-between;padding:13px 14px;border-radius:10px}
  .nav-lnk:hover{background:var(--glass2)}
  .nav-lnk{cursor:pointer}
  .mega{position:static;transform:none;opacity:1;visibility:visible;box-shadow:none;
    width:auto;max-width:none;padding:0 8px;border:0;background:transparent;
    max-height:0;overflow:hidden;transition:max-height .32s ease}
  .acc:checked ~ .mega{max-height:1400px;padding:4px 8px 14px}
  .acc:checked ~ .nav-lnk svg{transform:rotate(180deg)}
  .mega-grid{grid-template-columns:1fr 1fr;gap:10px 18px}
  .mega-foot{flex-direction:column;align-items:stretch}
  .nav-mcta{display:block;margin-top:6px}
  .nav-mcta .btn{width:100%;justify-content:center}
}
@media(max-width:600px){
  .cta-arrow{font-size:0;gap:0;padding:6px}
  .cta-arrow .arrb{width:34px;height:34px}
  .mega-grid{grid-template-columns:1fr}
}

/* ---------- hero ---------- */
.hero{position:relative;background:radial-gradient(1100px 560px at 82% -10%,rgba(247,168,10,.24),transparent 60%),radial-gradient(900px 520px at 4% 10%,rgba(59,130,246,.2),transparent 58%),linear-gradient(180deg,#0c1122,#070a14);
  color:#eaf0f8;overflow:hidden;isolation:isolate}
.hero .wrap{padding-top:clamp(46px,7vw,88px);padding-bottom:clamp(56px,8vw,104px)}
.aurora{position:absolute;inset:-40% -10% auto -10%;height:80%;z-index:-1;filter:blur(80px);opacity:.6;
  background:conic-gradient(from 120deg at 60% 40%,rgba(247,168,10,.55),rgba(255,200,71,.4),rgba(59,130,246,.3),rgba(247,168,10,.5));
  animation:auroraSpin 24s linear infinite}
@keyframes auroraSpin{to{transform:rotate(360deg)}}
.hero-grid{position:absolute;inset:0;z-index:-1;opacity:.5;
  background-image:linear-gradient(rgba(120,150,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(120,150,255,.06) 1px,transparent 1px);
  background-size:56px 56px;mask-image:radial-gradient(1100px 640px at 50% 0%,#000,transparent 78%)}
.hero-in{display:grid;grid-template-columns:1.34fr .66fr;gap:clamp(22px,2.6vw,40px);align-items:center}
.hero-eye{display:inline-flex;align-items:center;gap:9px;padding:7px 14px;border-radius:999px;
  background:var(--glass);border:1px solid var(--line2);backdrop-filter:blur(8px);
  font-family:var(--fdisp);font-weight:700;font-size:.76rem;letter-spacing:.13em;text-transform:uppercase;color:#ffd487}
.hero-eye .dot{width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 4px rgba(247,168,10,.28),0 0 12px var(--cyan);animation:pulse 2.2s infinite}
@keyframes pulse{50%{box-shadow:0 0 0 8px rgba(247,168,10,0),0 0 12px var(--cyan)}}
.hero h1{font-size:clamp(1.75rem,3.2vw,2.55rem);line-height:1.12;margin:18px 0 0;letter-spacing:-.018em}
.hero h1 .g{background:linear-gradient(100deg,#ffe08a,#ffb23a 40%,#f7a80a 70%,#ffd874);-webkit-background-clip:text;background-clip:text;color:transparent;
  background-size:220% auto;animation:sheen 6s linear infinite;filter:drop-shadow(0 0 24px rgba(247,168,10,.45))}
@keyframes sheen{to{background-position:220% center}}
.hero-sub{font-size:clamp(1.04rem,1.7vw,1.22rem);color:#b7c0da;max-width:34ch;margin:20px 0 0}
.vcl{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0 0}
.vcl .chip{display:inline-flex;align-items:center;gap:9px;padding:9px 15px;border-radius:12px;
  background:var(--glass);border:1px solid var(--line2);backdrop-filter:blur(8px);font-family:var(--fdisp);font-weight:700;font-size:.92rem}
.vcl .chip svg{width:17px;height:17px}
.vcl .c1 svg{color:var(--cyan)}.vcl .c2 svg{color:var(--violet)}.vcl .c3 svg{color:var(--blue)}
.hero-cta{display:flex;flex-wrap:wrap;gap:13px;margin:30px 0 0}
.hero-trust{display:flex;flex-wrap:wrap;align-items:center;gap:8px 20px;margin:26px 0 0;color:#9aa3c0;font-size:.9rem}
.hero-trust b{color:#fff}
.hero-trust .star{color:var(--cyan);letter-spacing:2px;filter:drop-shadow(0 0 8px rgba(247,168,10,.6))}

.stage{position:relative;min-height:440px;display:flex;align-items:center;justify-content:center}
.stage-glow{position:absolute;width:82%;aspect-ratio:1;border-radius:50%;
  background:radial-gradient(circle,rgba(247,168,10,.3),rgba(247,168,10,.16) 45%,transparent 66%);filter:blur(12px)}
.stage-ring{position:absolute;width:66%;aspect-ratio:1;border:1.5px solid rgba(247,168,10,.18);border-radius:50%;animation:spin 40s linear infinite}
.stage-ring.r2{width:84%;border-color:rgba(247,168,10,.14);border-style:dashed;animation-duration:60s;animation-direction:reverse}
@keyframes spin{to{transform:rotate(360deg)}}
/* animated Australia outline — sketches on load (pure CSS) */
.aus-map{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:122%;height:122%;z-index:1;pointer-events:none;overflow:visible}
.aus-p{fill:none;stroke:#ffc24a;stroke-width:2.4;stroke-linejoin:round;stroke-linecap:round;opacity:.85;
  filter:drop-shadow(0 0 5px rgba(247,168,10,.55));
  stroke-dasharray:1;stroke-dashoffset:1;animation:ausDraw 3.4s ease-in-out .35s forwards}
.aus-p2{animation-delay:3.5s;animation-duration:.9s}
@keyframes ausDraw{to{stroke-dashoffset:0}}
@media(prefers-reduced-motion:reduce){.aus-p{animation:none;stroke-dashoffset:0}}
.stage-char{position:relative;z-index:2;width:min(360px,86%);height:auto;aspect-ratio:1/1;object-fit:contain;
  filter:drop-shadow(0 22px 30px rgba(0,0,0,.45));animation:floatY 6s ease-in-out infinite}
@keyframes floatY{50%{transform:translateY(-14px)}}
.fcard{position:absolute;z-index:3;background:rgba(12,15,32,.82);color:var(--ink);border-radius:15px;
  padding:12px 15px;box-shadow:0 22px 44px -18px rgba(0,0,0,.7),0 0 0 1px var(--line2);backdrop-filter:blur(14px);
  font-family:var(--fdisp);animation:floatY 5s ease-in-out infinite}
.fcard small{display:block;font-family:var(--fbody);color:var(--mut);font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em}
.fcard .big{font-size:1.35rem;font-weight:800;line-height:1}
.fc-rank{top:2%;left:-11%;animation-delay:.4s}
.fc-rank .row{display:flex;align-items:center;gap:8px;margin-top:4px}
.fc-rank .bar{height:7px;border-radius:4px;background:linear-gradient(90deg,var(--cyan),var(--violet));width:64px;box-shadow:0 0 12px var(--gcyan)}
.fc-rank .row svg{color:var(--cyan)}
.fc-seo{bottom:9%;right:-13%;animation-delay:1.1s;border:1px solid rgba(247,168,10,.4)}
.fc-seo .big{color:#ffc247}
.fc-seo s{color:#7c86a5}
.fc-rev{bottom:-3%;left:-9%;animation-delay:.8s}
.fc-rev .star{color:var(--cyan);font-size:.9rem;letter-spacing:1px}
.fc-ico{position:absolute;top:-4%;right:-4%;z-index:3;width:56px;height:56px;border-radius:16px;
  background:linear-gradient(135deg,#ffc247,#f7a80a);display:flex;align-items:center;justify-content:center;
  box-shadow:0 0 30px -6px rgba(247,168,10,.6),0 0 40px -8px var(--gviolet);animation:floatY 5.5s ease-in-out infinite}
.fc-ico svg{width:30px;height:30px;color:#231704}
@media(max-width:900px){
  .hero{overflow-x:clip}
  .hero-in{grid-template-columns:1fr;gap:10px}
  .hero-sub{max-width:46ch}
  .stage{min-height:0;margin-top:38px;margin-bottom:14px;order:2;padding:6px 4px}
  .stage-char{height:min(340px,64vw)}
  /* pull the floating badges fully inside the stage so they never spill off a phone screen */
  .fc-rank{top:0;left:0;animation:none}
  .fc-seo{bottom:2%;right:0;animation:none}
  .fc-rev{bottom:0;left:0;animation:none}
  .fc-ico{top:-2%;right:0;animation:none}
  .fcard{padding:9px 12px;max-width:48vw}
  .fcard .big{font-size:1.02rem}
  .fcard small{font-size:.64rem}
}
@media(max-width:560px){
  .stage{margin-top:46px}
  .stage-char{height:min(300px,66vw)}
  .fc-rank{top:-4px;left:0}
  .fc-seo{bottom:4px;right:0}
  .fc-rev{bottom:-4px;left:0}
  .fc-ico{width:44px;height:44px;top:-4px;right:0}
  .fc-ico svg{width:24px;height:24px}
  .fcard{padding:8px 10px;max-width:46vw}
  .fcard .big{font-size:.95rem}
  .fc-seo .big{font-size:.9rem}
}

/* ---------- marquee ---------- */
.marq{background:rgba(8,10,24,.7);color:#8b93b2;padding:15px 0;overflow:hidden;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.marq-mask{display:flex;gap:0;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
.marq-row{display:flex;gap:44px;padding-right:44px;flex-shrink:0;animation:marq 34s linear infinite;white-space:nowrap}
@keyframes marq{to{transform:translateX(-100%)}}
.marq-row span{font-family:var(--fdisp);font-weight:700;font-size:1rem;display:inline-flex;align-items:center;gap:12px;color:#aeb6d4}
.marq-row span::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}

/* ---------- section shells ---------- */
.sec{padding:clamp(58px,8vw,104px) 0;position:relative}
/* Every dark section paints its own background so it does NOT depend on the
   page body (a CMS like Nifty renders on its own light canvas). Light 'rowlight'
   rows are excluded and keep their light background. background-color only, so
   sections with their own gradient (.proc/.quote) keep it layered on top. */
.sec:not(.rowlight){background-color:var(--bg)}
main{background-color:var(--bg)}
.sec-head{max-width:660px;margin:0 auto clamp(34px,5vw,52px);text-align:center}
.sec-head.left{margin-left:0;text-align:left}
.sec-head h2{font-size:clamp(1.85rem,3.6vw,2.9rem);margin:12px 0 0}
.sec-head p{color:var(--mut);font-size:1.08rem;margin:14px 0 0}

/* glass card base */
.vcl-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.vc{background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:28px;
  transition:transform .2s,box-shadow .2s,border-color .2s;position:relative;overflow:hidden;backdrop-filter:blur(12px)}
.vc:hover{transform:translateY(-6px);box-shadow:var(--glow);border-color:var(--line2)}
.vc::before{content:"";position:absolute;inset:0 0 auto 0;height:3px}
.vc.a::before{background:linear-gradient(90deg,var(--cyan),transparent)}
.vc.b::before{background:linear-gradient(90deg,var(--violet),transparent)}
.vc.c::before{background:linear-gradient(90deg,var(--blue),transparent)}
.vc-ic{width:56px;height:56px;border-radius:15px;display:flex;align-items:center;justify-content:center;margin-bottom:16px;border:1px solid var(--line2)}
.vc.a .vc-ic{background:rgba(247,168,10,.12)}.vc.a .vc-ic svg{color:var(--cyan)}
.vc.b .vc-ic{background:rgba(247,168,10,.14)}.vc.b .vc-ic svg{color:var(--violet)}
.vc.c .vc-ic{background:rgba(59,130,246,.14)}.vc.c .vc-ic svg{color:#7ab0ff}
.vc-ic svg{width:28px;height:28px}
.vc h3{font-size:1.3rem}
.vc p{color:var(--ink2);margin:10px 0 0;font-size:.98rem}
.vc .num{position:absolute;right:18px;top:12px;font-family:var(--fdisp);font-weight:800;
  font-size:2.6rem;color:rgba(255,255,255,.05);z-index:0}
@media(max-width:820px){.vcl-grid{grid-template-columns:1fr}}

/* free SEO build module */
.seo{background:linear-gradient(135deg,rgba(247,168,10,.08),rgba(247,168,10,.1));
  border:1px solid var(--line2);border-radius:26px;
  padding:clamp(30px,4.5vw,54px);position:relative;overflow:hidden;box-shadow:var(--shadow);backdrop-filter:blur(14px)}
.seo::after{content:"";position:absolute;width:460px;height:460px;right:-120px;top:-150px;border-radius:50%;
  background:radial-gradient(circle,rgba(247,168,10,.3),transparent 65%)}
.seo::before{content:"";position:absolute;width:420px;height:420px;left:-140px;bottom:-160px;border-radius:50%;
  background:radial-gradient(circle,rgba(247,168,10,.28),transparent 65%)}
.seo-in{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center;position:relative;z-index:2}
.seo-badge{display:inline-flex;align-items:center;gap:9px;background:rgba(247,168,10,.14);
  border:1px solid rgba(247,168,10,.4);color:#ffd487;padding:7px 14px;border-radius:999px;
  font-family:var(--fdisp);font-weight:700;font-size:.8rem;letter-spacing:.06em}
.seo h2{font-size:clamp(1.9rem,3.6vw,2.9rem);margin:16px 0 0}
.seo h2 em{font-style:normal;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.seo p{color:var(--ink2);margin:14px 0 0;max-width:44ch}
.seo-val{display:flex;align-items:center;gap:20px;margin-top:22px;flex-wrap:wrap}
.seo-val .n{flex:0 0 auto;font-family:var(--fdisp);font-weight:800;font-size:3rem;background:linear-gradient(100deg,#ffe08a,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;line-height:1;filter:drop-shadow(0 0 18px rgba(247,168,10,.5))}
.seo-val small{flex:1 1 170px;min-width:0;color:var(--mut);font-size:.9rem}
.seo-list{display:grid;gap:12px}
.seo-list li{list-style:none;display:flex;gap:12px;align-items:flex-start;
  background:var(--glass);border:1px solid var(--line);border-radius:13px;padding:13px 15px}
.seo-list .tick{width:26px;height:26px;border-radius:8px;background:linear-gradient(135deg,var(--cyan),var(--violet));display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 0 16px -4px var(--gcyan)}
.seo-list .tick svg{width:15px;height:15px;color:#04121a}
.seo-list b{font-family:var(--fdisp);font-size:.98rem}
.seo-list small{display:block;color:var(--mut);font-size:.84rem}
.seo-listhead{display:block;font-family:var(--fdisp);font-weight:800;font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:var(--amber);margin:0 0 14px}
.seo-inc{display:grid;grid-template-columns:1fr 1fr;gap:9px 18px;list-style:none;padding:0;margin:0}
.seo-inc li{display:flex;gap:10px;align-items:center;font-size:.92rem;color:var(--ink2);font-weight:500}
.seo-inc .tick{width:20px;height:20px;border-radius:6px;background:linear-gradient(135deg,var(--cyan),var(--violet));display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 0 12px -4px var(--gcyan)}
.seo-inc .tick svg{width:12px;height:12px;color:#04121a}
@media(max-width:860px){.seo-in{grid-template-columns:1fr;gap:26px}}
@media(max-width:520px){.seo-inc{grid-template-columns:1fr}}
/* --- offer animation: pulsing $2,000 + rippling ticks (pure CSS, no JS) --- */
@media (prefers-reduced-motion:no-preference){
  .seo-val{align-items:center}
  .seo-val .n{transform-origin:center;animation:pricePulse 2.4s ease-in-out infinite;will-change:transform}
  @keyframes pricePulse{
    0%,100%{transform:scale(1);filter:drop-shadow(0 0 14px rgba(247,168,10,.35))}
    50%{transform:scale(1.07);filter:drop-shadow(0 0 26px rgba(247,168,10,.7))}}
  .seo-list .tick{animation:tickBeat 3s ease-in-out infinite;will-change:transform}
  .seo-list li:nth-child(1) .tick{animation-delay:0s}
  .seo-list li:nth-child(2) .tick{animation-delay:.2s}
  .seo-list li:nth-child(3) .tick{animation-delay:.4s}
  .seo-list li:nth-child(4) .tick{animation-delay:.6s}
  @keyframes tickBeat{
    0%,58%,100%{transform:scale(1) rotate(0);box-shadow:0 0 16px -4px rgba(247,168,10,.5)}
    70%{transform:scale(1.28) rotate(8deg);box-shadow:0 0 24px 0 rgba(247,168,10,.85)}
    82%{transform:scale(.96) rotate(-2deg)}}
}

/* services grid */
.svc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.svc{background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:26px;
  transition:transform .2s,box-shadow .2s,border-color .2s;display:flex;flex-direction:column;backdrop-filter:blur(12px)}
.svc:hover{transform:translateY(-6px);box-shadow:var(--glow);border-color:var(--line2)}
.svc-ic{width:52px;height:52px;border-radius:14px;background:var(--glass2);border:1px solid var(--line2);display:flex;align-items:center;justify-content:center;margin-bottom:14px}
.svc-ic svg{width:26px;height:26px;color:var(--cyan)}
.svc.star{border-color:rgba(247,168,10,.45);background:linear-gradient(180deg,rgba(247,168,10,.1),rgba(247,168,10,.05))}
.svc.star .svc-ic{background:linear-gradient(135deg,#ffc247,#f7a80a);border:0;box-shadow:0 0 22px -6px rgba(247,168,10,.6)}
.svc.star .svc-ic svg{color:#231704}
.svc-badge{display:inline-block;background:linear-gradient(120deg,#ffc247,#f7a80a);color:#231704;font-family:var(--fdisp);font-weight:800;
  font-size:.68rem;letter-spacing:.06em;padding:3px 9px;border-radius:999px;margin-left:8px;vertical-align:middle}
.svc h3{font-size:1.18rem;display:flex;align-items:center;flex-wrap:wrap}
.svc p{color:var(--ink2);font-size:.94rem;margin:9px 0 14px}
.svc-links{margin:auto 0 0;display:flex;flex-wrap:wrap;gap:6px}
.svc-links a{font-size:.82rem;font-weight:600;color:var(--ink2);background:var(--glass2);border:1px solid var(--line);padding:5px 10px;border-radius:8px;transition:.14s}
.svc-links a:hover{background:linear-gradient(120deg,var(--cyan),var(--violet));color:#04121a;border-color:transparent}
@media(max-width:900px){.svc-grid{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.svc-grid{grid-template-columns:1fr}}

/* process */
.proc{background:linear-gradient(180deg,rgba(247,168,10,.05),transparent)}
.proc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;counter-reset:step}
.pstep{position:relative;background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:26px 22px;backdrop-filter:blur(12px);transition:transform .2s,border-color .2s}
.pstep:hover{transform:translateY(-5px);border-color:var(--line2)}
.pstep::before{counter-increment:step;content:"0" counter(step);font-family:var(--fdisp);font-weight:800;
  font-size:1rem;color:#04121a;background:linear-gradient(135deg,var(--cyan),#ffb23a);width:44px;height:44px;border-radius:12px;
  display:flex;align-items:center;justify-content:center;margin-bottom:14px;box-shadow:0 0 18px -6px var(--gcyan)}
.pstep.s2::before{background:linear-gradient(135deg,#f7a80a,#f7a80a);color:#fff}
.pstep.s3::before{background:linear-gradient(135deg,#f7a80a,#f7a80a);color:#fff}
.pstep.s4::before{background:linear-gradient(135deg,#f7a80a,#3b82f6);color:#fff}
.pstep h3{font-size:1.12rem}
.pstep p{color:var(--ink2);font-size:.92rem;margin:8px 0 0}
@media(max-width:900px){.proc-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.proc-grid{grid-template-columns:1fr}}

/* industries */
.ind-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(172px,1fr));gap:12px}
.ind-t{flex:1 1 auto;min-width:0;overflow-wrap:normal;line-height:1.2}
.ind{display:flex;align-items:center;gap:11px;background:var(--glass);border:1px solid var(--line);
  border-radius:13px;padding:14px 15px;font-family:var(--fdisp);font-weight:600;font-size:.94rem;transition:.16s;backdrop-filter:blur(10px)}
.ind:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -8px var(--gcyan)}
.ind .ii{width:34px;height:34px;border-radius:9px;background:rgba(247,168,10,.12);border:1px solid var(--line2);display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.16s}
.ind:hover .ii{background:linear-gradient(135deg,var(--cyan),var(--violet))}
.ind .ii svg{width:19px;height:19px;color:var(--cyan)}
.ind:hover .ii svg{color:#04121a}
.ind .cite{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan);margin-left:auto;flex-shrink:0}

/* portfolio — staggered browser-mockup gallery */
.pf-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(22px,3vw,40px);align-items:start}
.pf{display:block;transition:transform .25s}
.pf:hover{transform:translateY(-7px)}
.pf-frame{border-radius:16px;overflow:hidden;border:1px solid var(--line2);background:#0e1526;
  box-shadow:0 30px 60px -30px rgba(0,0,0,.75);transition:box-shadow .25s,border-color .25s}
.pf:hover .pf-frame{border-color:rgba(247,168,10,.4);box-shadow:0 34px 66px -28px rgba(0,0,0,.85),0 0 40px -18px rgba(247,168,10,.5)}
.pf-bar{display:flex;align-items:center;gap:7px;padding:11px 15px;background:#131b2e;border-bottom:1px solid var(--line)}
.pf-bar span{width:10px;height:10px;border-radius:50%;background:#3a4762;flex-shrink:0}
.pf-bar span:nth-child(1){background:#ff5f57}
