/* quote form */
.quote{background:radial-gradient(820px 440px at 90% -5%,rgba(247,168,10,.28),transparent 62%),radial-gradient(720px 420px at 4% 105%,rgba(59,130,246,.14),transparent 62%),linear-gradient(180deg,#f4f6fc,#eef2f9)}.quote .qform{background:#0f1526;border-color:rgba(255,255,255,.09)}
