.qr1:checked ~ .qform-body .qsteps .s1,
.qr2:checked ~ .qform-body .qsteps .s1,.qr2:checked ~ .qform-body .qsteps .s2,
.qr3:checked ~ .qform-body .qsteps .s1,.qr3:checked ~ .qform-body .qsteps .s2,.qr3:checked ~ .qform-body .qsteps .s3{background:linear-gradient(90deg,var(--cyan),var(--violet));box-shadow:0 0 12px -2px var(--gcyan)}
