/* CTA band — dark banner with thumbs-up character popping out */
.cta{background:radial-gradient(680px 320px at 86% 55%,rgba(247,168,10,.16),transparent 62%),linear-gradient(115deg,#0a1226,#0d1a33 46%,#141b12);
