/* ---------- sticky quote bot (pure CSS) ---------- */
.qbot-tog{position:fixed;opacity:0;pointer-events:none;width:0;height:0}
.qbot-tab{position:fixed;right:0;top:44%;transform:translateY(-50%);z-index:97;
  display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;
  background:linear-gradient(165deg,#121728,#0a0e1a);border:1px solid var(--line2);border-right:0;
  border-radius:18px 0 0 18px;padding:56px 13px 16px;
  box-shadow:-12px 0 40px -16px rgba(0,0,0,.7),0 0 34px -12px rgba(247,168,10,.45);
  transition:transform .45s cubic-bezier(.6,0,.2,1),box-shadow .2s}
.qbot-tab:hover{box-shadow:-12px 0 46px -14px rgba(0,0,0,.8),0 0 44px -8px rgba(247,168,10,.7)}
