@keyframes botBob{0%,100%{transform:translateX(-50%) translateY(0) rotate(0)}50%{transform:translateX(-50%) translateY(-7px) rotate(-2deg)}}
.qbot-tabtxt{writing-mode:vertical-rl;transform:rotate(180deg);font-family:var(--fdisp);font-weight:800;
  font-size:.72rem;letter-spacing:.13em;text-transform:uppercase;color:#fff;line-height:1}
