/* Dark "wallpaper" hero/banner — amber + blue glow over deep navy, subtle grid, soft fade */
.bn-band{position:relative;overflow:hidden;padding:clamp(60px,8vw,110px) 0;color:#eaf0f8;
  background:radial-gradient(1100px 560px at 82% -10%,rgba(247,168,10,.26),transparent 60%),
             radial-gradient(900px 520px at 4% 8%,rgba(59,130,246,.20),transparent 58%),
             linear-gradient(180deg,#0c1122,#070a14)}
.bn-band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;
  background-image:linear-gradient(rgba(120,150,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(120,150,255,.06) 1px,transparent 1px);
  background-size:56px 56px;
  -webkit-mask-image:radial-gradient(1000px 620px at 50% 18%,#000,transparent 78%);
  mask-image:radial-gradient(1000px 620px at 50% 18%,#000,transparent 78%)}
.bn-band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:120px;pointer-events:none;
  background:linear-gradient(180deg,transparent,var(--bg))}
.bn-band .wrap{position:relative;z-index:1;text-align:center;max-width:1000px}
