.pf-tag{font-family:var(--fdisp);font-weight:800;font-size:.68rem;letter-spacing:.06em;text-transform:uppercase;
  color:#231704;background:linear-gradient(120deg,#ffc247,#f7a80a);padding:5px 11px;border-radius:999px;flex-shrink:0}
