/* two doors */
.doors{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.door{border-radius:24px;padding:clamp(26px,3.5vw,40px);position:relative;overflow:hidden;backdrop-filter:blur(14px)}
.door.client{background:linear-gradient(160deg,rgba(247,168,10,.1),rgba(255,255,255,.02));border:1px solid rgba(247,168,10,.28)}
