.door .tag{font-family:var(--fdisp);font-weight:700;font-size:.76rem;letter-spacing:.13em;text-transform:uppercase}
.door.client .tag{color:var(--cyan)}.door.wl .tag{color:var(--blue-l)}
.door h3{font-size:clamp(1.4rem,2.4vw,1.9rem);margin:12px 0 0}
