/* pricing */
.price-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;align-items:stretch}
.plan{background:var(--glass);border:1px solid var(--line);border-radius:22px;padding:30px 26px;
  display:flex;flex-direction:column;position:relative;transition:transform .2s,box-shadow .2s,border-color .2s;backdrop-filter:blur(12px)}
.plan:hover{transform:translateY(-6px);box-shadow:var(--glow);border-color:var(--line2)}
.plan.pop{border:1px solid rgba(247,168,10,.5);box-shadow:0 0 40px -14px rgba(247,168,10,.5),0 0 60px -20px var(--gviolet);background:linear-gradient(180deg,rgba(247,168,10,.08),rgba(247,168,10,.05))}
.plan .pop-tag{position:absolute;top:-13px;left:50%;transform:translateX(-50%);background:linear-gradient(120deg,#ffc247,#f7a80a);
  color:#231704;font-family:var(--fdisp);font-weight:800;font-size:.72rem;letter-spacing:.06em;padding:5px 14px;border-radius:999px;box-shadow:0 0 20px -6px rgba(247,168,10,.6)}
.plan{overflow:visible}
.plan-charwrap{display:flex;justify-content:center;align-items:flex-end;height:132px;margin:-6px 0 4px;position:relative}
.plan-charwrap::before{content:"";position:absolute;bottom:2px;left:50%;transform:translateX(-50%);
  width:150px;height:44px;border-radius:50%;background:radial-gradient(closest-side,rgba(247,168,10,.28),transparent 78%);filter:blur(3px);z-index:0}
.plan-char{position:relative;z-index:1;height:150px;width:auto;object-fit:contain;
  filter:drop-shadow(0 14px 16px rgba(0,0,0,.5));transition:transform .3s cubic-bezier(.5,0,.2,1)}
.plan:hover .plan-char{transform:translateY(-6px) scale(1.03)}
.plan h3{font-size:1.2rem;text-align:center}
.plan-platform{display:block;text-align:center;font-family:var(--fdisp);font-weight:700;font-size:.7rem;letter-spacing:.06em;
  text-transform:uppercase;color:var(--amber);opacity:.9;margin:6px 0 2px}
.plan .from,.plan .amt{text-align:center}
.plan-pricearea{min-height:150px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px}
