.wasp{text-decoration:line-through;text-decoration-color:rgba(255,107,107,.8)}
.plan .save{align-self:center;text-align:center;margin:8px 0 0;color:#7cc142;font-weight:700;font-size:.82rem;
  background:rgba(124,193,66,.12);border:1px solid rgba(124,193,66,.35);border-radius:999px;padding:5px 12px}
.plan .save svg{width:13px;height:13px;vertical-align:-2px;color:#7cc142}
.plan-promo{position:absolute;top:14px;right:14px;background:linear-gradient(120deg,#ff6b6b,#e0413f);color:#fff;
  font-family:var(--fdisp);font-weight:800;font-size:.6rem;letter-spacing:.08em;text-transform:uppercase;padding:5px 10px;border-radius:8px;
  box-shadow:0 6px 18px -6px rgba(224,65,63,.6);z-index:3}
.promo-banner{margin:0 0 26px;text-align:center;background:linear-gradient(120deg,rgba(247,168,10,.14),rgba(247,168,10,.05));
  border:1px solid rgba(247,168,10,.4);border-radius:14px;padding:13px 20px;color:var(--ink2);font-size:.98rem}
