.price-note{max-width:920px;margin:30px auto 0;background:var(--glass);border:1px solid var(--line2);border-left:3px solid var(--amber);
  border-radius:12px;padding:16px 20px}
.price-note p{margin:0;color:var(--ink2);font-size:.94rem;line-height:1.6}
.price-note b{color:var(--ink)}
.plan .free{margin-left:auto;margin-right:auto}
.plan .from{color:var(--mut);font-size:.82rem;margin-top:14px}
.plan .amt{font-family:var(--fdisp);font-weight:800;font-size:2.5rem;line-height:1;margin-top:2px}
.plan .amt small{font-size:1rem;color:var(--mut);font-weight:600}
.plan .free{display:inline-flex;align-items:center;gap:7px;background:rgba(247,168,10,.12);border:1px solid rgba(247,168,10,.35);color:#ffd487;
  font-family:var(--fdisp);font-weight:700;font-size:.78rem;padding:5px 11px;border-radius:999px;margin-top:14px}
.plan .free svg{width:14px;height:14px}
.plan ul{list-style:none;padding:0;margin:18px 0 22px;display:grid;gap:10px}
.plan li{display:flex;gap:10px;font-size:.93rem;color:var(--ink2)}
