/* ---------- care plans: three billing cards ---------- */
.care-block{margin-top:46px}
.care-head{text-align:center;max-width:760px;margin:0 auto 30px}
.care-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;align-items:stretch}
.care-card{background:var(--glass);border:1px solid var(--line);border-radius:22px;padding:28px 24px;overflow:visible;
  display:flex;flex-direction:column;position:relative;transition:transform .2s,box-shadow .2s,border-color .2s;backdrop-filter:blur(12px)}
.care-card:hover{transform:translateY(-6px);box-shadow:var(--glow);border-color:var(--line2)}
.care-card.pop{border:1px solid rgba(247,168,10,.5);box-shadow:0 0 40px -14px rgba(247,168,10,.5);
  background:linear-gradient(180deg,rgba(247,168,10,.08),rgba(247,168,10,.05))}
