/* ===== Buy Now page — scoped styles (bn-*) ===== */
/* Dark "wallpaper" hero/banner — amber + blue glow over deep navy, subtle grid, soft fade */
.bn-band{position:relative;overflow:hidden;padding:clamp(60px,8vw,110px) 0;color:#eaf0f8;
  background:radial-gradient(1100px 560px at 82% -10%,rgba(247,168,10,.26),transparent 60%),
             radial-gradient(900px 520px at 4% 8%,rgba(59,130,246,.20),transparent 58%),
             linear-gradient(180deg,#0c1122,#070a14)}
.bn-band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;
  background-image:linear-gradient(rgba(120,150,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(120,150,255,.06) 1px,transparent 1px);
  background-size:56px 56px;
  -webkit-mask-image:radial-gradient(1000px 620px at 50% 18%,#000,transparent 78%);
  mask-image:radial-gradient(1000px 620px at 50% 18%,#000,transparent 78%)}
.bn-band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:120px;pointer-events:none;
  background:linear-gradient(180deg,transparent,var(--bg))}
.bn-band .wrap{position:relative;z-index:1;text-align:center;max-width:1000px}
.bn-ribbon{display:inline-flex;align-items:center;gap:.55em;background:rgba(247,168,10,.12);color:#ffce7a;
  border:1px solid rgba(247,168,10,.34);font-family:var(--fdisp);font-weight:800;font-size:.72rem;
  letter-spacing:.16em;text-transform:uppercase;padding:.5em 1.05em;border-radius:999px;margin-bottom:20px}
.bn-ribbon .dot{width:8px;height:8px;border-radius:50%;background:#f7a80a;box-shadow:0 0 0 0 rgba(247,168,10,.7);animation:bnPulse 1.8s infinite}
@keyframes bnPulse{0%{box-shadow:0 0 0 0 rgba(247,168,10,.6)}70%{box-shadow:0 0 0 9px rgba(247,168,10,0)}100%{box-shadow:0 0 0 0 rgba(247,168,10,0)}}
.bn-band h1{font-family:var(--fdisp);font-weight:800;line-height:1.04;margin:0 0 16px;
  font-size:clamp(2.1rem,5.2vw,3.8rem);color:#f4f7fd}
.bn-band .bn-sub{font-size:clamp(1.02rem,1.7vw,1.2rem);line-height:1.55;color:var(--ink2);max-width:760px;margin:0 auto 10px}
.bn-price{display:flex;align-items:baseline;justify-content:center;gap:.4em;margin:26px 0 6px}
.bn-price .cur{font-family:var(--fdisp);font-weight:800;font-size:clamp(1.4rem,3vw,2.2rem);align-self:flex-start;margin-top:.35em}
.bn-price .amt{font-family:var(--fdisp);font-weight:800;font-size:clamp(3rem,8vw,5.2rem);line-height:.9}
.bn-price .cur,.bn-price .amt{background:linear-gradient(100deg,#ffd874,#ffb23a 50%,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 18px rgba(247,168,10,.4))}
.bn-price .gst{font-family:var(--fdisp);font-weight:700;font-size:1rem;color:var(--mut)}
.bn-cta-wrap{margin-top:26px;display:flex;flex-direction:column;align-items:center;gap:14px}
.bn-buy{background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;font-family:var(--fdisp);font-weight:800;
  font-size:clamp(1.05rem,2vw,1.32rem);padding:1.05em 2.2em;border-radius:999px;display:inline-flex;
  align-items:center;gap:.6em;text-decoration:none;transition:transform .18s,box-shadow .18s;
  box-shadow:0 0 30px -6px rgba(247,168,10,.6),0 18px 42px -16px rgba(247,168,10,.5)}
.bn-buy:hover{transform:translateY(-3px);box-shadow:0 0 42px -4px rgba(247,168,10,.75),0 22px 50px -16px rgba(247,168,10,.55)}
.bn-buy svg{width:1.05em;height:1.05em}
.bn-micro{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 20px;font-family:var(--fdisp);font-weight:700;font-size:.85rem;color:var(--ink2)}
.bn-micro span{display:inline-flex;align-items:center;gap:.4em}
.bn-micro svg{width:15px;height:15px;stroke:#f7a80a}

/* Full-width concept showcase */
.bn-showcase{padding:clamp(20px,4vw,48px) 0 clamp(40px,6vw,80px)}
.bn-showcase .wrap{max-width:1180px}
.bn-shot-frame{position:relative;border-radius:18px;overflow:hidden;border:1px solid var(--line2);background:#0e1526;
  box-shadow:0 40px 90px -40px rgba(0,0,0,.8),0 0 60px -18px rgba(247,168,10,.28)}
.bn-shot-bar{display:flex;align-items:center;gap:7px;padding:12px 16px;background:#131b2e;border-bottom:1px solid var(--line)}
.bn-shot-bar span{width:11px;height:11px;border-radius:50%;background:#3a4762;flex-shrink:0}
.bn-shot-bar span:nth-child(1){background:#ff5f57}.bn-shot-bar span:nth-child(2){background:#febc2e}.bn-shot-bar span:nth-child(3){background:#28c840}
.bn-shot-url{margin-left:12px;font-style:normal;font-size:.78rem;color:#8b93b2;background:rgba(255,255,255,.06);padding:4px 16px;border-radius:999px;max-width:320px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.bn-shot-frame img{display:block;width:100%;height:auto}

/* how-it-works steps */
.bn-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.bn-step{background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:28px;position:relative;backdrop-filter:blur(12px)}
.bn-step .bn-num{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-family:var(--fdisp);font-weight:800;font-size:1.15rem;color:#231704;background:linear-gradient(135deg,#ffc247,#f7a80a);margin-bottom:16px;box-shadow:0 0 22px -6px rgba(247,168,10,.55)}
.bn-step h3{font-size:1.12rem;margin:0 0 8px}
.bn-step p{color:var(--ink2);font-size:.97rem;margin:0;line-height:1.55}

/* fine-print */
.bn-fine{background:var(--glass);border:1px solid var(--line2);border-radius:18px;padding:clamp(24px,4vw,40px);margin-top:8px}
.bn-fine-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px 34px;margin-top:10px}
.bn-fine-item{display:flex;gap:14px;align-items:flex-start}
.bn-fine-item .ic{flex:0 0 auto;width:38px;height:38px;border-radius:11px;display:flex;align-items:center;justify-content:center;background:rgba(247,168,10,.12);border:1px solid rgba(247,168,10,.32)}
.bn-fine-item .ic svg{width:19px;height:19px;stroke:var(--amber)}
.bn-fine-item h4{font-family:var(--fdisp);font-weight:700;font-size:1.02rem;margin:0 0 4px;color:var(--ink)}
.bn-fine-item p{color:var(--ink2);font-size:.93rem;line-height:1.55;margin:0}
.bn-note{color:var(--mut);font-size:.86rem;margin-top:22px;text-align:center;line-height:1.6}

/* two-column final CTA */
.bn-cta2{display:grid;grid-template-columns:1.02fr .98fr;gap:clamp(30px,5vw,64px);align-items:center;max-width:1180px;margin:0 auto;text-align:left}
.bn-cta2 .bn-l{text-align:left}
.bn-cta2 h1{text-align:left;margin-top:0}
.bn-cta2 .bn-sub{text-align:left;margin-left:0}
.bn-cta2 .bn-cta-wrap{align-items:flex-start}
.bn-cta2 .bn-micro{justify-content:flex-start}
.bn-cta-img{position:relative;border-radius:18px;overflow:hidden;border:1px solid var(--line2);background:#0e1526;box-shadow:0 40px 90px -40px rgba(0,0,0,.8),0 0 60px -18px rgba(247,168,10,.3)}
.bn-cta-img .bn-shot-bar{padding:11px 15px}
.bn-cta-img img{display:block;width:100%;height:auto}

@media(max-width:860px){.bn-steps{grid-template-columns:1fr}.bn-fine-grid{grid-template-columns:1fr}
  .bn-cta2{grid-template-columns:1fr;text-align:center}
  .bn-cta2 .bn-l,.bn-cta2 h1,.bn-cta2 .bn-sub{text-align:center}
  .bn-cta2 .bn-cta-wrap{align-items:center}.bn-cta2 .bn-micro{justify-content:center}
  .bn-cta2 .bn-cta-img{order:-1;margin-bottom:6px}}
